    byte[] buf = new byte[encodedSize(entry)];
    int off = 0;

    byte type;
    byte[] keyBytes = entry.key().toArray(java.lang.foreign.ValueLayout.JAVA_BYTE);
    long seqNum = entry.sequenceNumber().value();
